import {objectToQuery} from '@jetbrains/teamcity-ui/dist/utils'

import {restBaseApi} from '../../../services/restBase'

export type SetupResponse = {
  secretKey: string
  recoveryKeys: string[]
  uuid: string
}

type NewRecoveryKeysResponse = {
  recoveryKeys: string[]
}

type LoginResponse = {
  errorText?: string | null
  redirectUrl?: string | null
}

type ConfirmArg = {
  uuid: string
  password: number
}

export const twoFactorAuthApi = restBaseApi.injectEndpoints({
  endpoints: build => ({
    login: build.mutation<LoginResponse, string>({
      query: password => ({
        url: '/2fa.html',
        method: 'POST',
        headers: {
          'Content-Type': 'application/x-www-form-urlencoded; charset=UTF-8',
        },
        body: objectToQuery({password}),
        redirect: 'manual',
        responseHandler: 'text',
      }),
      transformResponse: (text: string) => {
        const xml = new DOMParser().parseFromString(text, 'text/xml')
        return {
          errorText: xml.querySelector('error')?.textContent,
          redirectUrl: xml.querySelector('redirect')?.textContent,
        }
      },
    }),
    generateRecoveryKeys: build.mutation<NewRecoveryKeysResponse, void>({
      query: () => ({url: '/app/rest/2FA/newRecoveryKeys', method: 'POST'}),
    }),
    setup2FA: build.mutation<SetupResponse, void>({
      query: () => ({url: '/app/rest/2FA/setup', method: 'POST'}),
    }),
    confirm: build.mutation<string, ConfirmArg>({
      query: params => ({
        url: '/app/rest/2FA/confirm',
        params,
        method: 'POST',
        responseHandler: 'text',
      }),
    }),
    disable2FA: build.mutation<string, string>({
      query: username => ({
        url: `/app/rest/2FA/username:${username}/disable`,
        method: 'DELETE',
        responseHandler: 'text',
      }),
    }),
  }),
})
