import TeamCityLogo from '@jetbrains/logos/teamcity/teamcity.svg'
import Button from '@jetbrains/ring-ui-built/components/button/button'
import Icon from '@jetbrains/ring-ui-built/components/icon/icon'
import Input from '@jetbrains/ring-ui-built/components/input/input'
import {useCallback, useState} from 'react'
import type * as React from 'react'

import {extractErrorMessage} from '../../../../utils/extractError'
import PageTitle from '../../../common/PageTitle/PageTitle'
import {twoFactorAuthApi} from '../TwoFactorAuthPages.rest'

import styles from './TwoFactorAuthLoginPage.module.css'

function LoginForm() {
  const [password, setPassword] = useState('')
  const [requestLogin, {loading, error}] = twoFactorAuthApi.endpoints.login.useMutation({
    selectFromResult: ({isLoading, data, error}) => ({
      loading: isLoading,
      error: error ?? data?.errorText,
    }),
  })
  const errorMessage = extractErrorMessage(error)
  const onSubmit = useCallback(
    async (event: React.SyntheticEvent) => {
      event?.preventDefault()
      const response = await requestLogin(password)
      const redirectUrl = 'data' in response ? response.data?.redirectUrl : null

      if (redirectUrl != null) {
        location.href = `${location.origin}${redirectUrl}`
      }
    },
    [requestLogin, password],
  )
  return (
    <form onSubmit={onSubmit} className={styles.form}>
      <p>
        {'Enter six-digit password from your authenticator app or one of the saved recovery codes.'}
      </p>
      <Input
        label="Six-digit password or recovery code"
        value={password}
        onChange={(e: React.ChangeEvent<HTMLInputElement>) => setPassword(e.target.value)}
        autoComplete="off"
        autoFocus
        className={styles.password}
      />
      <Button primary loader={loading} className={styles.wideButton} type="submit">
        {'Validate'}
      </Button>
      <div className={styles.errorPlaceholder}>
        {!loading && errorMessage && <div className={styles.error}>{errorMessage}</div>}
      </div>
    </form>
  )
}

type Props = {
  showMandatory2FAMessage: boolean
}

function TwoFactorAuthLoginPage({showMandatory2FAMessage}: Props) {
  return (
    <div className={styles.container}>
      <Icon className={styles.logo} glyph={TeamCityLogo} />
      <PageTitle className={styles.heading}>{'Two-Factor Authentication'}</PageTitle>
      {showMandatory2FAMessage ? (
        <p>
          {
            'You have not enabled two-factor authentication, which is mandatory on the server. Please contact your server administrator.'
          }
        </p>
      ) : (
        <LoginForm />
      )}
    </div>
  )
}

export default TwoFactorAuthLoginPage
